package stack

import "testing"

func TestPushAndPop(t *testing.T) {
	s := &Stack{}
	s.Push(1)
	s.Push(2)
	s.Push(3)
	if s.Pop() != 3 {
		t.Error("Pop should return 3")
	}
	if s.Pop() != 2 {
		t.Error("Pop should return 2")
	}
	if s.Size() != 1 {
		t.Errorf("size should be 1, got %d", s.Size())
	}
}

func TestPeek(t *testing.T) {
	s := &Stack{}
	s.Push("hello")
	if s.Peek() != "hello" {
		t.Error("Peek should return 'hello'")
	}
	if s.Size() != 1 {
		t.Error("Peek should not remove item")
	}
}

func TestIsEmpty(t *testing.T) {
	s := &Stack{}
	if !s.IsEmpty() {
		t.Error("new stack should be empty")
	}
	s.Push(42)
	if s.IsEmpty() {
		t.Error("stack with item should not be empty")
	}
}
